package plugins

import (
	"sort"
	"strings"

	"github.com/AvengeMedia/DankMaterialShell/core/internal/utils"
)

func FuzzySearch(query string, plugins []Plugin) []Plugin {
	if query == "" {
		return plugins
	}

	queryLower := strings.ToLower(query)
	return utils.Filter(plugins, func(p Plugin) bool {
		return fuzzyMatch(queryLower, strings.ToLower(p.Name)) ||
			fuzzyMatch(queryLower, strings.ToLower(p.Category)) ||
			fuzzyMatch(queryLower, strings.ToLower(p.Description)) ||
			fuzzyMatch(queryLower, strings.ToLower(p.Author))
	})
}

func fuzzyMatch(query, text string) bool {
	queryIdx := 0
	for _, char := range text {
		if queryIdx < len(query) && char == rune(query[queryIdx]) {
			queryIdx++
		}
	}
	return queryIdx == len(query)
}

func FilterByCategory(category string, plugins []Plugin) []Plugin {
	if category == "" {
		return plugins
	}
	categoryLower := strings.ToLower(category)
	return utils.Filter(plugins, func(p Plugin) bool {
		return strings.ToLower(p.Category) == categoryLower
	})
}

func FilterByCompositor(compositor string, plugins []Plugin) []Plugin {
	if compositor == "" {
		return plugins
	}
	compositorLower := strings.ToLower(compositor)
	return utils.Filter(plugins, func(p Plugin) bool {
		return utils.Any(p.Compositors, func(c string) bool {
			return strings.ToLower(c) == compositorLower
		})
	})
}

func FilterByCapability(capability string, plugins []Plugin) []Plugin {
	if capability == "" {
		return plugins
	}
	capabilityLower := strings.ToLower(capability)
	return utils.Filter(plugins, func(p Plugin) bool {
		return utils.Any(p.Capabilities, func(c string) bool {
			return strings.ToLower(c) == capabilityLower
		})
	})
}

func SortByFirstParty(plugins []Plugin) []Plugin {
	sort.SliceStable(plugins, func(i, j int) bool {
		if plugins[i].Featured != plugins[j].Featured {
			return plugins[i].Featured
		}
		isFirstPartyI := strings.HasPrefix(plugins[i].Repo, "https://github.com/AvengeMedia")
		isFirstPartyJ := strings.HasPrefix(plugins[j].Repo, "https://github.com/AvengeMedia")
		if isFirstPartyI != isFirstPartyJ {
			return isFirstPartyI
		}
		return false
	})
	return plugins
}

func FindByIDOrName(idOrName string, plugins []Plugin) *Plugin {
	if p, found := utils.Find(plugins, func(p Plugin) bool { return p.ID == idOrName }); found {
		return &p
	}
	if p, found := utils.Find(plugins, func(p Plugin) bool { return p.Name == idOrName }); found {
		return &p
	}
	return nil
}

package wp_color_management

import (
	"github.com/AvengeMedia/dankgo/wayland/client"
)

// OutputDescription is the named color encoding of an output's current image
// description. Zero fields mean the corresponding event was not delivered
// (ICC-based or unnamed parametric descriptions).
type OutputDescription struct {
	Primaries    uint32
	TF           uint32
	ReferenceLum uint32
}

// QueryOutputDescription fetches the current image description of an output.
// roundtrip must dispatch pending events on the caller's connection.
func QueryOutputDescription(mgr *WpColorManagerV1, output *client.Output, roundtrip func() error) (OutputDescription, bool) {
	var desc OutputDescription

	cmOutput, err := mgr.GetOutput(output)
	if err != nil {
		return desc, false
	}
	defer cmOutput.Destroy()

	imgDesc, err := cmOutput.GetImageDescription()
	if err != nil {
		return desc, false
	}
	defer imgDesc.Destroy()

	ready := false
	imgDesc.SetReadyHandler(func(WpImageDescriptionV1ReadyEvent) { ready = true })
	imgDesc.SetReady2Handler(func(WpImageDescriptionV1Ready2Event) { ready = true })
	if err := roundtrip(); err != nil || !ready {
		return desc, false
	}

	info, err := imgDesc.GetInformation()
	if err != nil {
		return desc, false
	}

	info.SetPrimariesNamedHandler(func(e WpImageDescriptionInfoV1PrimariesNamedEvent) {
		desc.Primaries = e.Primaries
	})
	info.SetTfNamedHandler(func(e WpImageDescriptionInfoV1TfNamedEvent) {
		desc.TF = e.Tf
	})
	info.SetLuminancesHandler(func(e WpImageDescriptionInfoV1LuminancesEvent) {
		desc.ReferenceLum = e.ReferenceLum
	})
	if err := roundtrip(); err != nil {
		return desc, false
	}

	return desc, true
}

package plugins

import (
	"fmt"

	"github.com/AvengeMedia/DankMaterialShell/core/internal/plugins"
	"github.com/AvengeMedia/DankMaterialShell/core/internal/server/models"
	"github.com/AvengeMedia/dankgo/ipc"
)

func HandleSearch(conn *ipc.ConnWriter, req ipc.Request) {
	query, ok := models.Get[string](req, "query")
	if !ok {
		models.RespondError(conn, req.ID, "missing or invalid 'query' parameter")
		return
	}

	registry, err := plugins.NewRegistry()
	if err != nil {
		models.RespondError(conn, req.ID, fmt.Sprintf("failed to create registry: %v", err))
		return
	}

	pluginList, err := registry.List()
	if err != nil {
		models.RespondError(conn, req.ID, fmt.Sprintf("failed to list plugins: %v", err))
		return
	}

	searchResults := plugins.FuzzySearch(query, pluginList)

	if category := models.GetOr(req, "category", ""); category != "" {
		searchResults = plugins.FilterByCategory(category, searchResults)
	}

	if compositor := models.GetOr(req, "compositor", ""); compositor != "" {
		searchResults = plugins.FilterByCompositor(compositor, searchResults)
	}

	if capability := models.GetOr(req, "capability", ""); capability != "" {
		searchResults = plugins.FilterByCapability(capability, searchResults)
	}

	searchResults = plugins.SortByFirstParty(searchResults)

	manager, err := plugins.NewManager()
	if err != nil {
		models.RespondError(conn, req.ID, fmt.Sprintf("failed to create manager: %v", err))
		return
	}

	result := make([]PluginInfo, len(searchResults))
	for i, p := range searchResults {
		installed, _ := manager.IsInstalled(p)
		info := pluginInfoFromPlugin(p)
		info.Installed = installed
		result[i] = info
	}

	models.Respond(conn, req.ID, result)
}
